'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),crypto=require('node:crypto');
const {environment,settle,deferred,json,cash,flow,TODAY}=require('./lts_v280_cash_harness.cjs');
const results=[];
async function test(name,fn){try{await fn();results.push({name,pass:true});console.log('PASS',name)}catch(e){results.push({name,pass:false,error:e.stack});console.log('FAIL',name,e.message)}}
const reads=e=>e.count('lts_browser_cash_today_v242');
const refresh=e=>e.ctx.__LTS_V178_REVIEW.refreshCashOnly();
const value=n=>{const c=cash();c.cash=n;c.available_total=n+100;return c};
(async()=>{
await test('Cash is recovered independently while old forecast remains pending',async()=>{const e=environment(),g=deferred();e.seed();e.routes.lts_browser_flow_v242=()=>g.promise;const heavy=e.ctx.__test179.startDashboard();await settle();e.ctx.__LTS_V227_TRANSPORT.invalidate();await settle();assert.equal(reads(e),1);assert.equal(e.snapshot().cash_complete,true);g.resolve(json(flow()));await heavy;});
await test('100 renders and active refresh calls share one cash request',async()=>{const e=environment(),g=deferred();e.routes.lts_browser_cash_today_v242=()=>g.promise;const p=refresh(e);for(let i=0;i<100;i++){e.ctx.ACC=['Consolidado','Itaú','C6','Bradesco'][i%4];e.ctx.render();refresh(e)}await settle();assert.equal(reads(e),1);assert.match(e.snapshot().flow_position_text,/Atualizando/);g.resolve(json(cash()));await p;await settle();for(let i=0;i<100;i++)e.ctx.render();await settle();assert.equal(reads(e),1);assert.equal(e.snapshot().cash_complete,true)});
await test('Two invalidations during cash retain one active request and only latest replacement',async()=>{const e=environment(),first=deferred(),second=deferred();e.routes.lts_browser_cash_today_v242=({count})=>count===1?first.promise:second.promise;const p=refresh(e);await settle();e.ctx.__LTS_V227_TRANSPORT.invalidate();e.ctx.__LTS_V227_TRANSPORT.invalidate();await settle();assert.equal(reads(e),1);first.resolve(json(value(900)));await settle();assert.equal(reads(e),2);assert.equal(e.snapshot().cash_has_data,false);second.resolve(json(value(700)));await p;await settle();assert.equal(e.ctx.__LTS_V178_STATE.cash.data.cash,700);assert.equal(reads(e),2)});
await test('Terminal 400 error is not retried by bank changes or render',async()=>{const e=environment();e.routes.lts_browser_cash_today_v242=()=>json({message:'synthetic terminal'},400);await refresh(e);await settle();for(let i=0;i<100;i++){e.ctx.ACC=i%2?'Itaú':'C6';e.ctx.render()}await settle();assert.equal(reads(e),1);assert.equal(e.ctx.__LTS_V178_STATE.cash.status,'error');assert.match(e.snapshot().flow_position_text,/indisponível/)});
await test('503 retry budget is exactly two attempts and never reopens on render',async()=>{const e=environment();e.routes.lts_browser_cash_today_v242=()=>json({message:'synthetic transient'},503);await refresh(e);await settle();assert.equal(reads(e),2);for(let i=0;i<100;i++)e.ctx.render();await settle();assert.equal(reads(e),2);assert.equal(e.ctx.__LTS_V178_STATE.cash.status,'error')});
await test('Incomplete ready payload stays unavailable with no retry loop',async()=>{const e=environment();e.routes.lts_browser_cash_today_v242=()=>json({...cash(),status:'incomplete',cash:null});await refresh(e);await settle();for(let i=0;i<30;i++)e.ctx.render();await settle();assert.equal(reads(e),1);assert.equal(e.snapshot().cash_complete,false);assert.match(e.snapshot().flow_position_text,/indisponível/)});
await test('Silent transport invalidation during getSession prevents stale dispatch and queues one current read',async()=>{const e=environment(),auth=deferred();e.ctx.__LTS_V178_STATE.awards.status='ready';let calls=0;e.ctx.S.auth.getSession=()=>++calls===1?auth.promise:Promise.resolve({data:{session:{access_token:'invented-current'}}});const p=refresh(e);await settle();assert.equal(reads(e),0);e.ctx.__LTS_V227_TRANSPORT.invalidate(false);auth.resolve({data:{session:{access_token:'invented-old'}}});await p;await settle();assert.equal(reads(e),1);assert.equal(e.snapshot().cash_complete,true)});
await test('Silent transport invalidation during response discards old payload and serializes replacement',async()=>{const e=environment(),g=deferred();e.routes.lts_browser_cash_today_v242=({count})=>count===1?g.promise:json(value(800));const p=refresh(e);await settle();e.ctx.__LTS_V227_TRANSPORT.invalidate(false);assert.equal(reads(e),1);g.resolve(json(value(900)));await p;await settle();assert.equal(reads(e),2);assert.equal(e.ctx.__LTS_V178_STATE.cash.data.cash,800)});
await test('BOOT generation swap without render rejects prior response and recovers current session',async()=>{const e=environment(),g=deferred();e.routes.lts_browser_cash_today_v242=({count})=>count===1?g.promise:json(value(800));const p=refresh(e);await settle();e.ctx.sessionStorage.getItem=()=>String(e.ctx.Date.now());e.ctx.BOOT.generation++;e.ctx.D={newSession:true};g.resolve(json(value(900)));await p;await settle();assert.equal(reads(e),2);assert.equal(e.ctx.__LTS_V178_STATE.cash.data.cash,800);assert.equal(e.snapshot().cash_complete,true)});
await test('Logout while cash waits never applies old response or starts a replacement',async()=>{const e=environment(),g=deferred();e.routes.lts_browser_cash_today_v242=()=>g.promise;const p=refresh(e);await settle();e.ctx.BOOT.generation++;e.ctx.D=null;g.resolve(json(cash()));await p;await settle();assert.equal(reads(e),1);assert.equal(e.ctx.__LTS_V178_STATE.cash.data,undefined);assert.equal(e.ctx.__LTS_V178_STATE.cash.status,'idle')});
await test('BRT midnight rejects prior-day payload without advancing global dashboard day',async()=>{const e=environment(),g=deferred();e.seed();e.routes.lts_browser_cash_today_v242=({count})=>{if(count===1)return g.promise;const c=value(800);c.as_of='2026-10-17';return json(c)};const p=e.ctx.__LTS_V178_REVIEW.refreshCashOnly(true);await settle();e.advance(16*3600000);assert.equal(e.ctx.__test179.day(),'2026-10-17');g.resolve(json(value(900)));await p;await settle();assert.equal(reads(e),2);assert.equal(e.ctx.__LTS_V178_STATE.cash.data.cash,800);assert.equal(e.ctx.__LTS_V178_STATE.date,TODAY);assert.equal(e.snapshot().cash_complete,true)});
await test('Flow refresh continuation preserves current account/range/expansion',async()=>{const e=environment(),g=deferred();e.seed();e.routes.lts_browser_cash_today_v242=()=>g.promise;e.ctx.EXP.add('d-2031-02-03');const p=e.ctx.__test225.refreshScreens();await settle();e.ctx.ACC='C6';e.ctx.FLOWFROM='2031-02-03';e.ctx.FLOWTO='2031-02-05';g.resolve(json(cash()));await p;await settle();assert.equal(e.ctx.ACC,'C6');assert.equal(e.ctx.FLOWFROM,'2031-02-03');assert.equal(e.ctx.FLOWTO,'2031-02-05');assert(e.ctx.EXP.has('d-2031-02-03'));assert.equal(e.count('loadFlowRange'),1)});
await test('Full V226 layer allows exactly one invalidation for Flow refreshScreens',async()=>{const e=environment();e.seed();e.ctx.openCardSettlement=async()=>{};const source=fs.readFileSync('releases/v280/lts-v226-card-composition.js','utf8'),start=source.indexOf('function runtime()'),end=source.indexOf('\n  let tries=',start);require('node:vm').runInContext('('+source.slice(start,end).trim()+')();',e.ctx);e.routes.lts_browser_card_cycles_v229=()=>json({version:'card-cycles-v226',cards:[]});let events=0;e.ctx.addEventListener('lts:data-invalidated',()=>events++);const before=e.ctx.__LTS_V227_TRANSPORT.revision;await e.ctx.__test225.refreshScreens();await settle();assert.equal(events,1);assert.equal(e.ctx.__LTS_V227_TRANSPORT.revision-before,1)});
await test('Queued old Dashboard refresh does not restart heavy reads after logout/new session',async()=>{const e=environment(),g=deferred();e.seed();e.ctx.V='Dashboard';e.routes.lts_browser_flow_v242=({count})=>count===1?g.promise:json(flow());const first=e.ctx.__test179.startDashboard();await settle();const old=e.ctx.__test179.startDashboard(true);await settle();e.ctx.D=null;e.ctx.BOOT.generation++;e.ctx.__test179.syncCashContext();e.ctx.D={newSession:true};e.ctx.BOOT.generation++;e.ctx.V='Fluxo Diário';e.ctx.__LTS_V225.sessionGeneration=e.ctx.BOOT.generation;e.ctx.__LTS_V225.started=true;e.ctx.sessionStorage.getItem=()=>String(e.ctx.Date.now());await refresh(e);await settle();const before=e.calls.length;g.resolve(json(flow()));await Promise.all([first,old]);await settle();assert.deepEqual(e.calls.slice(before).map(x=>x.name),[]) });
await test('Full V226 layer allows exactly one invalidation for Dashboard refreshScreens',async()=>{const e=environment();e.seed();e.ctx.openCardSettlement=async()=>{};const source=fs.readFileSync('releases/v280/lts-v226-card-composition.js','utf8'),start=source.indexOf('function runtime()'),end=source.indexOf('\n  let tries=',start);require('node:vm').runInContext('('+source.slice(start,end).trim()+')();',e.ctx);e.routes.lts_browser_card_cycles_v229=()=>json({version:'card-cycles-v226',cards:[]});e.ctx.V='Dashboard';let events=0;e.ctx.addEventListener('lts:data-invalidated',()=>events++);const before=e.ctx.__LTS_V227_TRANSPORT.revision;await e.ctx.__test225.refreshScreens();await settle();assert.equal(events,1);assert.equal(e.ctx.__LTS_V227_TRANSPORT.revision-before,1)});

await test('Queued Dashboard refreshes coalesce to the latest serial rather than replaying every old intent',async()=>{const e=environment(),g=deferred();e.seed();e.ctx.V='Dashboard';e.routes.lts_browser_flow_v242=({count})=>count===1?g.promise:json(flow());const first=e.ctx.__test179.startDashboard();await settle();const a=e.ctx.__test179.startDashboard(true),b=e.ctx.__test179.startDashboard(true);await settle();g.resolve(json(flow()));await Promise.all([first,a,b]);await settle();assert.equal(e.count('lts_browser_flow_v242'),2)});
await test('Cash-only invalidation repaints pending text without an external render',async()=>{const e=environment(),g=deferred();e.seed();e.ctx.render();assert.match(e.nodes.get('v274ReceivedPosition').textContent,/600,00/);e.routes.lts_browser_cash_today_v242=()=>g.promise;e.ctx.__LTS_V227_TRANSPORT.invalidate();await settle();assert.equal(e.ctx.__LTS_V178_STATE.cash.status,'loading');assert.match(e.nodes.get('v274ReceivedPosition').textContent,/Atualizando/);assert.doesNotMatch(e.nodes.get('v274ReceivedPosition').textContent,/600,00/);g.resolve(json(cash()));await settle()});
await test('Absent BOOT uses product identity to reject old-session response',async()=>{const e=environment(),g=deferred();delete e.ctx.BOOT;e.ctx.sessionStorage.getItem=()=>String(e.ctx.Date.now());e.ctx.__LTS_V225.sessionGeneration=e.ctx.D;e.routes.lts_browser_cash_today_v242=({count})=>count===1?g.promise:json(value(800));const p=refresh(e);await settle();e.ctx.D={newSession:true};e.ctx.__LTS_V225.sessionGeneration=e.ctx.D;g.resolve(json(value(900)));await p;await settle();assert.equal(reads(e),2);assert.equal(e.ctx.__LTS_V178_STATE.cash.data.cash,800);assert.equal(e.snapshot().cash_complete,true)});

const names=['lts-v179-cash-recovery.js','lts-v225-open-finance.js','lts-v228-bank-flow.js'];
const out={passed:results.filter(x=>x.pass).length,failed:results.filter(x=>!x.pass),checks:results,hashes:Object.fromEntries(names.map(n=>[n,crypto.createHash('sha256').update(fs.readFileSync('releases/v280/'+n)).digest('hex')]))};fs.writeFileSync('qa/v280-cash-independent-results.json',JSON.stringify(out,null,2));console.log('RESULT',out.passed,'PASS',out.failed.length,'FAIL');if(out.failed.length)process.exitCode=1;
})();
